function c215BuildTopicFilters() {
  var tags = {}, i, filters = [{ id: "all", label: "All" }], seen = {}, oi, tag;
  for (i = 0; i < QA200.length; i++) { tags[QA200[i].t] = true; }
  for (oi = 0; oi < C215_TOPIC_FILTER_ORDER.length; oi++) {
    tag = C215_TOPIC_FILTER_ORDER[oi];
    if (tags[tag]) {
      filters.push({ id: tag, label: C215_TOPIC_LABELS[tag] || tag });
      seen[tag] = true;
    }
  }
  for (tag in tags) {
    if (
      Object.prototype.hasOwnProperty.call(tags, tag) &&
      !seen[tag]
    ) {
      filters.push({ id: tag, label: C215_TOPIC_LABELS[tag] || tag });
    }
  }
  return filters;
}

function c215FilterIsValid(filterId) {
  var fi;
  for (fi = 0; fi < C215_FC_FILTERS.length; fi++) {
    if (C215_FC_FILTERS[fi].id === filterId) { return true; }
  }
  return false;
}

var C215_FC_FILTERS = c215BuildTopicFilters();
var C215_QZ_FILTERS = C215_FC_FILTERS.slice();

var C215_FC = [];
var C215_QZ = [];
(function buildData() {
  var i, item, pool, wrongs, opts, correctPos;
  for (i = 0; i < QA200.length; i++) {
    item = QA200[i];
    C215_FC.push({ t: item.t, q: item.q, a: item.a, e: item.exp, trick: item.trick || false, n: item.n });
    pool = [];
    var j;
    if (item.d && item.d.length >= 3) {
      pool = item.d.slice(0);
    } else {
      for (j = 0; j < QA200.length; j++) {
        if (j !== i && QA200[j].t === item.t && QA200[j].a !== item.a) { pool.push(QA200[j].a); }
      }
      if (pool.length < 3) {
        for (j = 0; j < QA200.length; j++) {
          if (j !== i && QA200[j].t !== item.t && QA200[j].a !== item.a) { pool.push(QA200[j].a); }
        }
      }
    }
    pool.sort(function() { return Math.random() - 0.5; });
    wrongs = pool.slice(0, 3);
    opts = wrongs.slice(0, 3);
    correctPos = Math.floor(Math.random() * 4);
    opts.splice(correctPos, 0, item.a);
    C215_QZ.push({ t: item.t, m: item.m || 0, q: item.q, opts: opts, a: correctPos, e: item.exp, trick: item.trick || false, n: item.n });
  }
})();

