function c215StorageKey(suffix) {
  var uid = "c215_guest";
  if (window.Clerk && window.Clerk.user && window.Clerk.user.id) { uid = window.Clerk.user.id; }
  return "c215_" + suffix + "__" + uid;
}

function c215LoadStore() {
  try {
    var raw = localStorage.getItem(c215StorageKey("state"));
    if (raw) {
      var saved = JSON.parse(raw);
      if (saved.activeTab) {
        c215State.activeTab = saved.activeTab === "quickref" ? "cheats" : saved.activeTab;
        if (c215State.activeTab === "topics") { c215State.activeTab = "cheats"; c215State.cheatView = "notes"; }
        if (c215State.activeTab === "progress" || c215State.activeTab === "exammap" || c215State.activeTab === "cards") { c215State.activeTab = "course"; }
      }
      if (saved.cheatView) { c215State.cheatView = saved.cheatView; }
      if (saved.fcRatings) { c215State.fc.ratings = saved.fcRatings; }
      if (saved.qzTopicScores) { c215State.qz.topicScores = saved.qzTopicScores; }
      if (saved.mastered) { c215State.mastered = saved.mastered; }
      if (saved.tabDots) { c215State.tabDots = saved.tabDots; }
      if (saved.topicsOpen) { c215State.topicsOpen = saved.topicsOpen; }
      if (saved.mnemHide) { c215State.mnemHide = saved.mnemHide; }
    }
  } catch (e) {}
  if (!c215State.mastered) { c215State.mastered = {}; }
  if (!c215State.tabDots) { c215State.tabDots = {}; }
}

function c215SaveStore() {
  try {
    localStorage.setItem(c215StorageKey("state"), JSON.stringify({
      activeTab: c215State.activeTab,
      fcRatings: c215State.fc.ratings,
      qzTopicScores: c215State.qz.topicScores,
      mastered: c215State.mastered,
      tabDots: c215State.tabDots,
      topicsOpen: c215State.topicsOpen,
      cheatView: c215State.cheatView,
      mnemHide: c215State.mnemHide
    }));
  } catch (e) {}
}

function c215MasteredCount() {
  var n = 0, k;
  for (k in c215State.mastered) {
    if (
      Object.prototype.hasOwnProperty.call(c215State.mastered, k) &&
      c215State.mastered[k]
    ) {
      n++;
    }
  }
  return n;
}

function c215El(tag, cls, text) {
  var e = document.createElement(tag);
  if (cls) { e.className = cls; }
  if (text !== undefined) { e.textContent = text; }
  return e;
}

function c215TabDotColor(tabId) {
  if (tabId === "exammap") { return ""; }
  if (c215State.tabDots[tabId] === "green") { return "green"; }
  if (c215State.tabDots[tabId] === "yellow") { return "yellow"; }
  return "gray";
}

function c215UpdateTabDot(tabId, color) {
  if (tabId === "exammap") { return; }
  var cur = c215State.tabDots[tabId];
  if (color === "green") { c215State.tabDots[tabId] = "green"; }
  else if (color === "yellow" && cur !== "green") { c215State.tabDots[tabId] = "yellow"; }
  else if (!cur) { c215State.tabDots[tabId] = color; }
  c215SaveStore();
}

function c215FcStats() {
  var got = 0, almost = 0, missed = 0, keys = Object.keys(c215State.fc.ratings), ki;
  for (ki = 0; ki < keys.length; ki++) {
    if (c215State.fc.ratings[keys[ki]] === "got") { got++; }
    else if (c215State.fc.ratings[keys[ki]] === "almost") { almost++; }
    else if (c215State.fc.ratings[keys[ki]] === "missed") { missed++; }
  }
  return { got: got, almost: almost, missed: missed };
}

function c215Render() {
  var root = document.getElementById("cha-course215-root");
  if (!root) { return; }
  root.innerHTML = "";
  var top = c215El("div", "c215x-top");
  var hdr = c215El("div", "c215-hdr");
  hdr.innerHTML = "<h1 class=\"c215-title\">2-15 Study Guide</h1>"
    + "<p class=\"c215-subtitle\">Florida Health and Life -- 2026 exam. New? Start at Module 1.</p>";
  top.appendChild(hdr);
  var tabBar = c215El("div", "c215-tabs");
  tabBar.setAttribute("role", "tablist");
  var ti, tab, btn;
  for (ti = 0; ti < C215_TABS.length; ti++) {
    tab = C215_TABS[ti];
    (function(t) {
      btn = c215El("button", "c215-tab" + (c215State.activeTab === t.id ? " active" : ""));
      btn.type = "button";
      btn.setAttribute("role", "tab");
      btn.setAttribute("aria-selected", c215State.activeTab === t.id ? "true" : "false");
      btn.appendChild(document.createTextNode(t.label));
      btn.onclick = function() { c215SwitchTab(t.id); };
      tabBar.appendChild(btn);
    })(tab);
  }
  top.appendChild(tabBar);
  root.appendChild(top);
  var body = c215El("div", "c215-body");
  body.id = "c215Body";
  root.appendChild(body);
  c215RenderTab(body);
  c215RenderBrainModal(root);
}

function c215SwitchTab(id) {
  if (id === "course" && c215State.activeTab !== "course") { c215Course.view = "home"; }
  c215State.activeTab = id;
  c215UpdateTabDot(id, "yellow");
  c215SaveStore();
  c215Render();
}

function c215RenderTab(container) {
  var id = c215State.activeTab;
  if (id === "course") { c215RenderCourse(container); return; }
  if (id === "exammap") { c215RenderExamMap(container); return; }
  if (id === "cards") { c215RenderCards(container); return; }
  if (id === "quiz") { c215RenderQuiz(container); return; }
  if (id === "topics") { c215State.cheatView = "notes"; c215RenderCheats(container); return; }
  if (id === "cheats") { c215RenderCheats(container); return; }
  if (id === "progress") { c215RenderExamMap(container); return; }
  c215RenderCourse(container);
}

function c215FormatBrainDumpLine(text) {
  var idx = text.indexOf(":");
  if (idx > 0) {
    return "<li><strong>" + text.substring(0, idx) + "</strong>" + text.substring(idx) + "</li>";
  }
  return "<li><strong>" + text + "</strong></li>";
}

function c215FcTopicLabel(topicId) {
  var labels = { life: "Life", health: "Health", fl: "Florida law", annuity: "Annuities", provisions: "Provisions", disability: "Disability", medicare: "Medicare", trade: "Trade practices" };
  return labels[topicId] || topicId;
}

function c215TransformCompareHtml(html) {
  if (html.indexOf("c215-compare") < 0) { return html; }
  return html.replace(/<div class="c215-compare">([\s\S]*?)<\/div>/g, function(_, inner) {
    var sides = [], sideRe = /<div class="c215-compare-side">([\s\S]*?)<\/div>/g, m, out = "<div class=\"c215-compare\">", si, sideHtml, titleMatch, title, hdClass, rowsHtml, liRe, lm;
    while ((m = sideRe.exec(inner)) !== null) { sides.push(m[1]); }
    for (si = 0; si < sides.length; si++) {
      sideHtml = sides[si];
      titleMatch = sideHtml.match(/<h4>([\s\S]*?)<\/h4>/);
      title = titleMatch ? titleMatch[1] : "";
      hdClass = si === 0 ? "c215-compare-hd c215-compare-hd-left" : "c215-compare-hd c215-compare-hd-right";
      rowsHtml = "";
      liRe = /<li>([\s\S]*?)<\/li>/g;
      while ((lm = liRe.exec(sideHtml)) !== null) {
        rowsHtml += "<div class=\"c215-compare-row\">" + lm[1] + "</div>";
      }
      out += "<div class=\"c215-compare-card\"><div class=\"" + hdClass + "\">" + title + "</div>";
      out += "<div class=\"c215-compare-body\">" + rowsHtml + "</div></div>";
    }
    return out + "</div>";
  });
}

function c215WrapCheatTables(html, title) {
  if (html.indexOf("c215-table") < 0) { return html; }
  return html.replace(/<table class="c215-table">([\s\S]*?)<\/table>/g, function(_, inner) {
    var thead = "", tbody = inner, firstTrMatch = inner.match(/^\s*<tr>[\s\S]*?<\/tr>/);
    if (firstTrMatch && (firstTrMatch[0].indexOf("<th>") >= 0 || firstTrMatch[0].indexOf("<th ") >= 0)) {
      thead = "<thead>" + firstTrMatch[0] + "</thead>";
      tbody = inner.slice(firstTrMatch[0].length);
    }
    return "<div class=\"c215-cheat-table-wrap\"><div class=\"c215-cheat-table-hd\">"
      + "<div class=\"c215-cheat-table-title\">" + title + "</div></div>"
      + "<table class=\"c215-table\">" + thead + "<tbody>" + tbody + "</tbody></table></div>";
  });
}

function c215EnhanceCheatHtml(html, title) {
  return c215WrapCheatTables(c215TransformCompareHtml(html), title);
}

function c215BuildMnemonicsHtml() {
  var html = "", mi, m, hidden;
  for (mi = 0; mi < C215_MNEMONICS.length; mi++) {
    m = C215_MNEMONICS[mi];
    hidden = !!c215State.mnemHide[m.id];
    html += "<div class=\"c215-mnem-card\"><div class=\"c215-mnem-top\">";
    html += "<div class=\"c215-mnem-phrase\">" + m.phrase + "</div>";
    html += "<button type=\"button\" class=\"c215-btn-sm\" onclick=\"c215ToggleMnem('" + m.id + "')\">" + (hidden ? "Show" : "Test Yourself") + "</button></div>";
    html += "<div class=\"c215-mnem-body" + (hidden ? " hidden" : "") + "\">" + m.html + "</div></div>";
  }
  return html;
}

function c215RenderExamMap(container) {
  var html = "", wi, mastered = c215MasteredCount();
  var total = QA200.length;
  var pct = total > 0 ? Math.round(mastered / total * 100) : 0;
  var stats = c215FcStats();
  html += "<div class=\"c215x-ov\">";
  html += "<div class=\"c215x-col\">";
  html += "<div class=\"c215x-hero\"><div class=\"c215x-hero-txt\">";
  html += "<span class=\"c215x-eyebrow\">Start here</span>";
  html += "<span class=\"c215x-hero-title\">FL Statutes -- Common to All Lines</span>";
  html += "<span class=\"c215x-hero-sub\">Biggest section on the exam -- 13%. Florida law is one third of the test.</span></div>";
  html += "<button type=\"button\" class=\"c215x-btn-light\" onclick=\"c215QzFilter('fl')\">Practice FL law</button></div>";
  html += "<div class=\"c215x-stats\">";
  html += "<div class=\"c215x-stat\"><span class=\"c215x-stat-n\">150</span><span class=\"c215x-stat-l\">scored questions (+15 unscored)</span></div>";
  html += "<div class=\"c215x-stat\"><span class=\"c215x-stat-n\">2h 45m</span><span class=\"c215x-stat-l\">time limit</span></div>";
  html += "<div class=\"c215x-stat\"><span class=\"c215x-stat-n\">70%</span><span class=\"c215x-stat-l\">to pass -- 105 correct</span></div></div>";
  html += "<div class=\"c215x-card\"><div class=\"c215x-card-hd\"><h2>My progress</h2><span>" + mastered + " of " + total + " mastered</span></div>";
  html += "<div class=\"c215x-bar c215x-bar-lg\"><div class=\"c215x-bar-fill\" style=\"width:" + pct + "%\"></div></div>";
  html += "<div class=\"c215x-mini\">Study cards: " + stats.got + " got it, " + stats.almost + " almost, " + stats.missed + " missed</div>";
  html += "<div class=\"c215x-actions\">";
  html += "<button type=\"button\" class=\"c215x-btn-soft\" onclick=\"c215SwitchTab('cards')\">Study cards</button>";
  html += "<button type=\"button\" class=\"c215x-btn-soft\" onclick=\"c215OpenBrain(true)\">Brain dump list</button>";
  html += "<button type=\"button\" class=\"c215x-btn-ghost\" onclick=\"c215ResetProgress()\">Reset progress</button>";
  html += "</div></div>";
  html += "</div>";
  html += "<div class=\"c215x-card c215x-map\"><h2>Exam map -- 2026 official weights</h2>";
  html += "<p class=\"c215x-map-sub\">Pearson VUE outline effective January 1, 2026</p>";
  for (wi = 0; wi < C215_EXAM_WEIGHTS.length; wi++) {
    var w = C215_EXAM_WEIGHTS[wi];
    html += "<div class=\"c215x-map-row\"><span class=\"c215x-map-name\">" + w.name + "</span>";
    html += "<div class=\"c215x-bar\"><div class=\"c215x-bar-fill\" style=\"width:" + Math.round(w.pct / 13 * 100) + "%\"></div></div>";
    html += "<span class=\"c215x-map-pct\">" + w.pct + "%</span></div>";
  }
  html += "</div></div>";
  container.innerHTML = html;
}

function c215ToggleMnem(id) {
  c215State.mnemHide[id] = !c215State.mnemHide[id];
  c215SaveStore();
  var body = document.getElementById("c215Body");
  if (body) { c215RenderTab(body); }
}

function c215FcApplyFilter(filter) {
  if (!c215FilterIsValid(filter)) { filter = "all"; }
  c215State.fc.filter = filter;
  if (filter === "all") { c215State.fc.queue = C215_FC.slice(); }
  else { c215State.fc.queue = C215_FC.filter(function(c) { return c.t === filter; }); }
  c215State.fc.idx = 0;
}

function c215RenderCards(container) {
  if (c215State.fc.queue.length === 0) { c215FcApplyFilter("all"); }
  var html = "<div class=\"c215-cards-wrap\">";
  html += "<div class=\"c215-filters\">";
  var fi, f;
  for (fi = 0; fi < C215_FC_FILTERS.length; fi++) {
    f = C215_FC_FILTERS[fi];
    html += "<button type=\"button\" class=\"c215-filter" + (c215State.fc.filter === f.id ? " active" : "") + "\" onclick=\"c215FcFilter('" + f.id + "')\">" + f.label + "</button>";
  }
  html += "</div>";
  var progPct = c215State.fc.queue.length > 0 ? Math.round((c215State.fc.idx + 1) / c215State.fc.queue.length * 100) : 0;
  html += "<div class=\"c215-prog\"><div class=\"c215-prog-fill\" style=\"width:" + progPct + "%\"></div></div>";
  html += "<div class=\"c215-fc-count\">Card " + (c215State.fc.queue.length > 0 ? c215State.fc.idx + 1 : 0) + " of " + c215State.fc.queue.length + "</div>";
  var card = c215State.fc.queue.length > 0 ? c215State.fc.queue[c215State.fc.idx] : null;
  html += "<div class=\"c215-fc-area\">";
  if (card) { html += "<span class=\"c215-fc-topic\">" + c215FcTopicLabel(card.t) + "</span>"; }
  html += "<div class=\"c215-stack\">";
  html += "<div class=\"c215-stack-2\"></div><div class=\"c215-stack-1\"></div>";
  html += "<div class=\"c215-study-card\" id=\"c215StudyCard\" onclick=\"c215FcFlip()\">";
  if (card) {
    html += "<div class=\"c215-study-front\">";
    html += "<span class=\"c215-study-label\">Question</span>";
    html += "<div class=\"c215-study-q\">" + card.q + "</div>";
    html += "<span class=\"c215-study-hint\">Tap to reveal answer</span>";
    html += "</div>";
    html += "<div class=\"c215-study-back\">";
    html += "<span class=\"c215-study-label\">Answer</span>";
    html += "<div class=\"c215-study-a\">" + card.a + "</div>";
    html += "<div class=\"c215-study-e\">" + card.e + "</div>";
    html += "</div>";
  } else {
    html += "<div class=\"c215-study-front\"><span class=\"c215-study-hint\">No cards in this filter.</span></div>";
  }
  html += "</div></div></div>";
  html += "<div class=\"c215-rate-row\">";
  html += "<button type=\"button\" class=\"c215-rate c215-rate-got\" id=\"c215RateGot\" style=\"display:none\" onclick=\"c215FcRate('got')\">Got It</button>";
  html += "<button type=\"button\" class=\"c215-rate c215-rate-almost\" id=\"c215RateAlmost\" style=\"display:none\" onclick=\"c215FcRate('almost')\">Almost</button>";
  html += "<button type=\"button\" class=\"c215-rate c215-rate-missed\" id=\"c215RateMissed\" style=\"display:none\" onclick=\"c215FcRate('missed')\">Missed It</button>";
  html += "</div></div>";
  container.innerHTML = html;
}

function c215ShowRateButtons() {
  var got = document.getElementById("c215RateGot");
  var almost = document.getElementById("c215RateAlmost");
  var missed = document.getElementById("c215RateMissed");
  if (got) { got.style.display = "inline-block"; }
  if (almost) { almost.style.display = "inline-block"; }
  if (missed) { missed.style.display = "inline-block"; }
}

function c215FcFlip() {
  var el = document.getElementById("c215StudyCard");
  if (!el || el.className.indexOf("flipped") >= 0) { return; }
  el.className = "c215-study-card flipped";
  c215ShowRateButtons();
}

function c215FcRate(result) {
  var item = c215State.fc.queue[c215State.fc.idx];
  if (!item) { return; }
  var origIdx = item.n - 1;
  c215State.fc.ratings[origIdx] = result;
  if (result === "got") {
    c215State.mastered["q" + item.n] = true;
    c215UpdateTabDot("cards", "green");
  } else if (result === "almost" || result === "missed") {
    var copy = { t: item.t, q: item.q, a: item.a, e: item.e, trick: item.trick, n: item.n };
    c215State.fc.queue.push(copy);
  }
  c215SaveStore();
  if (c215State.fc.idx < c215State.fc.queue.length - 1) { c215State.fc.idx++; }
  else { c215State.fc.idx = 0; }
  c215SwitchTab("cards");
}

function c215FcFilter(filter) { c215FcApplyFilter(filter); c215SwitchTab("cards"); }

function c215QzApplyFilter(filter) {
  if (!c215FilterIsValid(filter)) { filter = "all"; }
  c215State.qz.filter = filter;
  var pool, i;
  if (filter === "all") { pool = C215_QZ.slice(); }
  else { pool = C215_QZ.filter(function(q) { return q.t === filter; }); }
  if (c215State.qz.missedOnly) {
    var missedPool = [];
    for (i = 0; i < pool.length; i++) {
      if (c215State.fc.ratings[pool[i].n - 1] === "missed") { missedPool.push(pool[i]); }
    }
    pool = missedPool.length > 0 ? missedPool : pool;
  }
  pool.sort(function() { return Math.random() - 0.5; });
  c215State.qz.queue = pool;
  c215State.qz.idx = 0;
  c215State.qz.correct = 0;
  c215State.qz.total = 0;
  c215State.qz.answered = false;
}

function c215RenderQuiz(container) {
  if (c215State.qz.queue.length === 0) { c215QzApplyFilter("all"); }
  var html = "<div class=\"c215-quiz-wrap c215x-focus\">";
  html += "<div class=\"c215x-toolbar\"><div class=\"c215-filters\">";
  var fi, f;
  for (fi = 0; fi < C215_QZ_FILTERS.length; fi++) {
    f = C215_QZ_FILTERS[fi];
    html += "<button type=\"button\" class=\"c215-filter" + (c215State.qz.filter === f.id ? " active" : "") + "\" onclick=\"c215QzFilter('" + f.id + "')\">" + f.label + "</button>";
  }
  html += "</div>";
  html += "<label class=\"c215-missed-toggle\"><input type=\"checkbox\" " + (c215State.qz.missedOnly ? "checked" : "") + " onchange=\"c215QzMissedOnly(this.checked)\"> Missed only</label></div>";
  var n = c215State.qz.queue.length;
  if (c215State.qz.idx >= n && c215State.qz.total > 0) {
    var pct = Math.round(c215State.qz.correct / c215State.qz.total * 100);
    html += "<div class=\"c215x-qcard c215x-done\"><span class=\"c215x-eyebrow-dark\">Round complete</span>";
    html += "<div class=\"c215-qz-pct\">" + pct + "%</div>";
    html += "<p class=\"c215x-done-sub\">" + c215State.qz.correct + " of " + c215State.qz.total + " correct. You need 70% on the real exam.</p>";
    html += "<button type=\"button\" class=\"c215x-btn-dark\" onclick=\"c215QzRestart()\">Try again</button></div></div>";
    container.innerHTML = html; return;
  }
  var q = c215State.qz.queue[c215State.qz.idx];
  var barPct = n > 0 ? Math.round(c215State.qz.idx / n * 100) : 0;
  html += "<div class=\"c215x-qmeta\"><span>" + (q ? c215FcTopicLabel(q.t) : "") + "</span>";
  html += "<span>Question " + Math.min(c215State.qz.idx + 1, n) + " of " + n + " -- " + c215State.qz.correct + " correct</span></div>";
  html += "<div class=\"c215x-bar\"><div class=\"c215x-bar-fill c215x-bar-dark\" style=\"width:" + barPct + "%\"></div></div>";
  if (q) {
    html += "<div class=\"c215-qz-card c215x-qcard\"><div class=\"c215-qz-q\">" + q.q + "</div><div class=\"c215-qz-opts\" id=\"c215QzOpts\">";
    var oi;
    for (oi = 0; oi < q.opts.length; oi++) {
      html += "<button type=\"button\" class=\"c215-qz-opt\" onclick=\"c215QzAnswer(" + oi + "," + q.a + ")\"><span class=\"c215x-key\">" + String.fromCharCode(65 + oi) + "</span><span class=\"c215x-opt-txt\">" + q.opts[oi] + "</span></button>";
    }
    html += "</div><div class=\"c215-qz-explain\" id=\"c215QzExplain\"></div></div>";
    html += "<button type=\"button\" class=\"c215-qz-next\" id=\"c215QzNext\" onclick=\"c215QzNext()\">Next question</button>";
  }
  html += "</div>";
  container.innerHTML = html;
}

function c215QzFilter(filter) { c215QzApplyFilter(filter); c215SwitchTab("quiz"); }
function c215QzMissedOnly(on) { c215State.qz.missedOnly = on; c215QzApplyFilter(c215State.qz.filter); c215SwitchTab("quiz"); }

function c215QzAnswer(selected, correct) {
  if (c215State.qz.answered) { return; }
  c215State.qz.answered = true;
  c215State.qz.total++;
  var isCorrect = selected === correct;
  if (isCorrect) { c215State.qz.correct++; }
  var q = c215State.qz.queue[c215State.qz.idx];
  var topic = q.t || "life";
  if (!c215State.qz.topicScores[topic]) { c215State.qz.topicScores[topic] = { correct: 0, total: 0 }; }
  c215State.qz.topicScores[topic].total++;
  if (isCorrect) { c215State.qz.topicScores[topic].correct++; }
  if (!c215State.qz.topicScores.all) { c215State.qz.topicScores.all = { correct: 0, total: 0 }; }
  c215State.qz.topicScores.all.total++;
  if (isCorrect) { c215State.qz.topicScores.all.correct++; }
  if (isCorrect) { c215State.mastered["q" + q.n] = true; }
  c215UpdateTabDot("quiz", "yellow");
  if (c215State.qz.correct === c215State.qz.total && c215State.qz.total > 10) { c215UpdateTabDot("quiz", "green"); }
  c215SaveStore();
  var opts = document.querySelectorAll(".c215-qz-opt"), i;
  for (i = 0; i < opts.length; i++) {
    opts[i].disabled = true;
    if (i === correct) { opts[i].className = "c215-qz-opt correct"; }
    else if (i === selected && !isCorrect) { opts[i].className = "c215-qz-opt wrong"; }
  }
  var explainEl = document.getElementById("c215QzExplain");
  if (explainEl) {
    explainEl.textContent = (isCorrect ? "Correct. " : "Not quite. The answer is " + q.opts[correct] + ". ") + q.e;
    explainEl.className = "c215-qz-explain show " + (isCorrect ? "is-right" : "is-wrong");
  }
  var nextBtn = document.getElementById("c215QzNext");
  if (nextBtn) { nextBtn.className = "c215-qz-next show"; }
}

function c215QzNext() { c215State.qz.answered = false; c215State.qz.idx++; c215SwitchTab("quiz"); }
function c215QzRestart() { c215QzApplyFilter(c215State.qz.filter); c215SwitchTab("quiz"); }

function c215RenderTopics(container) {
  var html = "", ti, topic, gi, g, isOpen;
  for (ti = 0; ti < C215_ALL_TOPICS.length; ti++) {
    topic = C215_ALL_TOPICS[ti];
    isOpen = c215State.topicsOpen === topic.id;
    html += "<div class=\"c215-acc" + (isOpen ? " open" : "") + "\">";
    html += "<button type=\"button\" class=\"c215-acc-hd c215-acc-hd-" + topic.id + "\" onclick=\"c215ToggleTopic('" + topic.id + "')\">";
    html += "<span>" + topic.title + "</span><span class=\"c215-chev\">&#9662;</span></button>";
    html += "<div class=\"c215-acc-body\"><div class=\"c215-acc-in\">";
    for (gi = 0; gi < topic.groups.length; gi++) {
      g = topic.groups[gi];
      if (g.title && g.title !== "Overview") {
        html += "<div class=\"c215-subhd\">" + g.title + "</div>";
      }
      html += g.html;
    }
    html += "</div></div></div>";
  }
  container.innerHTML = html;
  c215WireNumCards(container);
}

function c215ToggleTopic(id) {
  if (c215State.topicsOpen === id) { c215State.topicsOpen = ""; }
  else { c215State.topicsOpen = id; }
  c215SaveStore();
  var body = document.getElementById("c215Body");
  if (body) { c215RenderTab(body); }
}

function c215WireNumCards(container) {
  var cards = container.querySelectorAll(".c215-numcard");
  var ci;
  for (ci = 0; ci < cards.length; ci++) {
    (function(card, idx) {
      card.onclick = function() {
        if (card.className.indexOf("flipped") >= 0) { card.className = "c215-numcard"; }
        else { card.className = "c215-numcard flipped"; }
      };
    })(cards[ci], ci);
  }
}

function c215CheatView(id) {
  c215State.cheatView = id;
  c215SaveStore();
  var body = document.getElementById("c215Body");
  if (body) { c215RenderTab(body); }
}

function c215RenderCheats(container) {
  var html = "", gi, g, bi, vi, v;
  var view = c215State.cheatView || "sheets";
  html += "<div class=\"c215x-subtabs\">";
  for (vi = 0; vi < C215_CHEAT_VIEWS.length; vi++) {
    v = C215_CHEAT_VIEWS[vi];
    html += "<button type=\"button\" class=\"c215x-subtab" + (view === v.id ? " active" : "") + "\" onclick=\"c215CheatView('" + v.id + "')\">" + v.label + "</button>";
  }
  html += "</div>";
  if (view === "notes") {
    container.innerHTML = html + "<div id=\"c215NotesBox\"></div>";
    c215RenderTopics(document.getElementById("c215NotesBox"));
    return;
  }
  if (view === "mnem") {
    container.innerHTML = html + "<div class=\"c215x-stack\">" + c215BuildMnemonicsHtml() + "</div>";
    return;
  }
  if (view === "brain") {
    html += "<div class=\"c215x-card\"><div class=\"c215x-card-hd\"><h2>Brain dump</h2><span>Write these on scratch paper before Question 1</span></div>";
    html += "<ul class=\"c215-brain-list\">";
    for (bi = 0; bi < C215_BRAIN_DUMP.length; bi++) {
      html += c215FormatBrainDumpLine(C215_BRAIN_DUMP[bi]);
    }
    html += "</ul></div>";
    container.innerHTML = html;
    return;
  }
  html += "<div class=\"c215x-stack\">";
  for (gi = 0; gi < C215_CHEAT_SHEETS.length; gi++) {
    g = C215_CHEAT_SHEETS[gi];
    if (!g.title || g.title === "Overview") { continue; }
    if (g.html.indexOf("c215-table") < 0 && g.html.indexOf("c215-compare") < 0) {
      html += "<div class=\"c215-subhd\">" + g.title + "</div>";
    }
    html += c215EnhanceCheatHtml(g.html, g.title);
  }
  html += "</div>";
  container.innerHTML = html;
}

function c215RenderProgress(container) {
  var mastered = c215MasteredCount();
  var pct = Math.round(mastered / QA200.length * 100);
  var stats = c215FcStats();
  var html = "<div class=\"c215-card-block\"><h2 class=\"c215-card-hd\">Overall Mastery</h2>";
  html += "<div class=\"c215-prog-big\"><div class=\"c215-prog-fill\" style=\"width:" + pct + "%\"></div></div>";
  html += "<div class=\"c215-prog-pct\">" + pct + "% (" + mastered + " of " + QA200.length + ")</div></div>";
  html += "<div class=\"c215-card-block\"><h2 class=\"c215-card-hd\">Quiz by Topic</h2>";
  var topics = ["fl", "life", "health", "annuity", "trade", "all"];
  var labels = { fl: "FL", life: "Life", health: "Health", annuity: "Annuities", trade: "Trade", all: "All" };
  var ti, sc, barPct;
  for (ti = 0; ti < topics.length; ti++) {
    sc = c215State.qz.topicScores[topics[ti]];
    if (sc && sc.total > 0) {
      barPct = Math.round(sc.correct / sc.total * 100);
      html += "<div class=\"c215-prog-topic\"><div class=\"c215-prog-topic-hd\"><span>" + labels[topics[ti]] + "</span>";
      html += "<span>" + sc.correct + " / " + sc.total + "</span></div>";
      html += "<div class=\"c215-prog\"><div class=\"c215-prog-fill\" style=\"width:" + barPct + "%\"></div></div></div>";
    }
  }
  html += "</div>";
  html += "<div class=\"c215-card-block\"><h2 class=\"c215-card-hd\">Flashcard Ratings</h2>";
  html += "<div class=\"c215-ratings\">Got It: " + stats.got + " | Almost: " + stats.almost + " | Missed: " + stats.missed + "</div></div>";
  html += "<button type=\"button\" class=\"c215-reset-btn\" onclick=\"c215ResetProgress()\">Reset All Progress</button>";
  container.innerHTML = html;
}

function c215ResetProgress() {
  if (!window.confirm("Reset all progress? This cannot be undone.")) { return; }
  c215State.mastered = {};
  c215State.fc.ratings = {};
  c215State.fc.idx = 0;
  c215State.qz.topicScores = {};
  c215State.qz.correct = 0;
  c215State.qz.total = 0;
  c215State.tabDots = {};
  c215State.mnemHide = {};
  c215SaveStore();
  try { localStorage.removeItem(c215StorageKey("state")); } catch (e) {}
  c215LoadStore();
  c215SwitchTab("course");
}

function c215RenderBrainModal(root) {
  var overlay = c215El("div", "c215-modal-bg" + (c215State.brainOpen ? " show" : ""));
  overlay.id = "c215BrainOverlay";
  overlay.onclick = function(e) { if (e.target === overlay) { c215OpenBrain(false); } };
  var modal = c215El("div", "c215-modal");
  var mh = "<button type=\"button\" class=\"c215-modal-x\" aria-label=\"Close\" onclick=\"c215OpenBrain(false)\">&times;</button>";
  mh += "<h3>Brain Dump</h3><p class=\"c215-modal-sub\">Write on scratch paper before Question 1</p><ul>";
  var bi;
  for (bi = 0; bi < C215_BRAIN_DUMP.length; bi++) { mh += "<li>" + C215_BRAIN_DUMP[bi] + "</li>"; }
  mh += "</ul>";
  modal.innerHTML = mh;
  overlay.appendChild(modal);
  root.appendChild(overlay);
}

function c215OpenBrain(open) {
  c215State.brainOpen = open;
  var ov = document.getElementById("c215BrainOverlay");
  if (ov) { ov.className = "c215-modal-bg" + (open ? " show" : ""); }
}

/* -- BEGINNER COURSE (Oct 2026) -- lessons come from js/course-215-lessons.js (window.C215_COURSE) -- */
var C215_TOPIC_TO_MODULES = { life: [2, 3], annuity: [4], health: [6, 7], fl: [10, 11, 12], trade: [10] };
var C215_PASS_MODULE = 80;
var C215_PASS_FINAL = 70;
var C215_FINAL_SIZE = 150;
var c215Course = { view: "home", mod: 1, lesson: 0, read: {}, done: {}, scores: {}, best: 0, name: "", certDate: "", run: null };

function c215CourseData() { return window.C215_COURSE || []; }

function c215CourseLoad() {
  try {
    var raw = localStorage.getItem(c215StorageKey("course"));
    if (raw) {
      var sv = JSON.parse(raw);
      c215Course.read = sv.read || {};
      c215Course.done = sv.done || {};
      c215Course.scores = sv.scores || {};
      c215Course.best = sv.best || 0;
      c215Course.name = sv.name || "";
      c215Course.certDate = sv.certDate || "";
    }
  } catch (e) { c215Course.read = {}; }
}

function c215CourseSave() {
  try {
    localStorage.setItem(c215StorageKey("course"), JSON.stringify({
      read: c215Course.read, done: c215Course.done, scores: c215Course.scores,
      best: c215Course.best, name: c215Course.name, certDate: c215Course.certDate
    }));
  } catch (e) { return; }
}

function c215Esc(t) {
  return String(t).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");
}

function c215CourseDoneCount() {
  var n = 0, k;
  for (k in c215Course.done) { if (Object.prototype.hasOwnProperty.call(c215Course.done, k) && c215Course.done[k]) { n++; } }
  return n;
}

function c215CourseNextModule() {
  var mods = c215CourseData(), i;
  for (i = 0; i < mods.length; i++) { if (!c215Course.done["m" + mods[i].n]) { return mods[i]; } }
  return null;
}

function c215CourseGo(view, mod, lesson) {
  c215Course.view = view;
  if (mod) { c215Course.mod = mod; }
  c215Course.lesson = lesson || 0;
  if (view === "check") { c215CourseStartRun("check"); }
  if (view === "final") { c215CourseStartRun("final"); }
  var body = document.getElementById("c215Body");
  if (body) { c215RenderCourse(body); }
  var root = document.getElementById("cha-course215-root");
  if (root && root.scrollIntoView) { root.scrollIntoView({ block: "start" }); }
}

function c215CourseQuestionsFor(modN) {
  var out = [], i, q, mods;
  for (i = 0; i < C215_QZ.length; i++) {
    q = C215_QZ[i];
    if (q.m) { if (q.m === modN) { out.push(q); } continue; }
    mods = C215_TOPIC_TO_MODULES[q.t] || [];
    if (mods.indexOf(modN) >= 0) { out.push(q); }
  }
  return out;
}

function c215Shuffle(arr) {
  var a = arr.slice(0), i, j, tmp;
  for (i = a.length - 1; i > 0; i--) { j = Math.floor(Math.random() * (i + 1)); tmp = a[i]; a[i] = a[j]; a[j] = tmp; }
  return a;
}

function c215CourseStartRun(kind) {
  var pool = kind === "final" ? C215_QZ.slice(0) : c215CourseQuestionsFor(c215Course.mod);
  var size = kind === "final" ? C215_FINAL_SIZE : 10;
  pool = c215Shuffle(pool).slice(0, size);
  c215Course.run = { kind: kind, qs: pool, idx: 0, correct: 0, answered: false, picked: -1, log: [] };
}

function c215CourseAnswer(i) {
  var r = c215Course.run;
  if (!r || r.answered) { return; }
  r.answered = true;
  r.picked = i;
  if (i === r.qs[r.idx].a) { r.correct++; }
  r.log.push({ q: r.qs[r.idx], picked: i, ok: i === r.qs[r.idx].a });
  var body = document.getElementById("c215Body");
  if (body) { c215RenderCourse(body); }
}

function c215CourseNextQ() {
  var r = c215Course.run;
  if (!r) { return; }
  r.idx++;
  r.answered = false;
  r.picked = -1;
  if (r.idx >= r.qs.length) {
    var pct = r.qs.length ? Math.round(r.correct / r.qs.length * 100) : 0;
    if (r.kind === "check") {
      c215Course.scores["m" + c215Course.mod] = Math.max(pct, c215Course.scores["m" + c215Course.mod] || 0);
      if (pct >= C215_PASS_MODULE) { c215Course.done["m" + c215Course.mod] = true; }
    } else {
      c215Course.best = Math.max(pct, c215Course.best || 0);
      if (pct >= C215_PASS_FINAL && !c215Course.certDate) {
        var d = new Date();
        c215Course.certDate = (d.getMonth() + 1) + "/" + d.getDate() + "/" + d.getFullYear();
      }
    }
    r.pct = pct;
    c215CourseSave();
  }
  var body = document.getElementById("c215Body");
  if (body) { c215RenderCourse(body); }
}

function c215CourseLessonNext() {
  var mod = c215CourseFind(c215Course.mod);
  if (!mod) { return; }
  c215Course.read["m" + mod.n + "l" + c215Course.lesson] = true;
  c215CourseSave();
  if (c215Course.lesson < mod.lessons.length - 1) { c215CourseGo("lesson", mod.n, c215Course.lesson + 1); }
  else { c215CourseGo("check", mod.n, 0); }
}

function c215CourseFind(n) {
  var mods = c215CourseData(), i;
  for (i = 0; i < mods.length; i++) { if (mods[i].n === n) { return mods[i]; } }
  return null;
}

function c215CourseSetName(v) {
  c215Course.name = String(v || "").slice(0, 80);
  c215CourseSave();
  var el = document.getElementById("c215CertName");
  if (el) { el.textContent = c215Course.name || "[Your name]"; }
}

function c215CoursePrint() {
  document.body.className += " c215-printing";
  window.print();
  setTimeout(function() { document.body.className = document.body.className.replace(/\s*c215-printing/g, ""); }, 500);
}

function c215RenderCourse(container) {
  var v = c215Course.view;
  if (v === "module") { c215RenderModule(container); return; }
  if (v === "lesson") { c215RenderLesson(container); return; }
  if (v === "check" || v === "final") { c215RenderRun(container); return; }
  if (v === "cert") { c215RenderCert(container); return; }
  c215RenderCourseHome(container);
}

function c215RenderCourseHome(container) {
  var mods = c215CourseData(), html = "", i, m, done, score, next = c215CourseNextModule();
  var total = mods.length + 1, doneN = c215CourseDoneCount() + (c215Course.best >= C215_PASS_FINAL ? 1 : 0);
  html += "<div class=\"c215x-ov c215c-home\"><div class=\"c215x-card c215c-list\">";
  html += "<div class=\"c215x-card-hd\"><h2>Course</h2><span>" + doneN + " of " + total + " done</span></div>";
  html += "<div class=\"c215x-bar c215x-bar-lg\"><div class=\"c215x-bar-fill\" style=\"width:" + Math.round(doneN / total * 100) + "%\"></div></div>";
  html += "<div class=\"c215c-rows\">";
  for (i = 0; i < mods.length; i++) {
    m = mods[i];
    done = !!c215Course.done["m" + m.n];
    score = c215Course.scores["m" + m.n];
    html += "<button type=\"button\" class=\"c215c-row" + (next && next.n === m.n ? " is-next" : "") + "\" onclick=\"c215CourseGo('module'," + m.n + ",0)\">";
    html += "<span class=\"c215c-badge" + (done ? " is-done" : "") + "\">" + (done ? "&#10003;" : m.n) + "</span>";
    html += "<span class=\"c215c-row-txt\"><span class=\"c215c-row-title\">Module " + m.n + " -- " + c215Esc(m.title) + "</span>";
    html += "<span class=\"c215c-row-sub\">" + c215Esc(m.sub) + "</span></span>";
    if (done || score) { html += "<span class=\"c215c-tag" + (done ? " is-done" : "") + "\">" + (done ? "Passed " + score + "%" : "Best " + score + "%") + "</span>"; }
    html += "</button>";
  }
  html += "<button type=\"button\" class=\"c215c-row c215c-final\" onclick=\"c215CourseGo('final')\">";
  html += "<span class=\"c215c-badge" + (c215Course.best >= C215_PASS_FINAL ? " is-done" : "") + "\">F</span>";
  html += "<span class=\"c215c-row-txt\"><span class=\"c215c-row-title\">Final Practice Exam</span>";
  html += "<span class=\"c215c-row-sub\">150 questions -- 70% to pass, like the real test</span></span>";
  if (c215Course.best) { html += "<span class=\"c215c-tag" + (c215Course.best >= C215_PASS_FINAL ? " is-done" : "") + "\">Best " + c215Course.best + "%</span>"; }
  html += "</button>";
  html += "</div></div>";
  html += "<div class=\"c215x-col\">";
  html += "<div class=\"c215x-hero c215c-next\"><div class=\"c215x-hero-txt\"><span class=\"c215x-eyebrow\">Next up</span>";
  if (next) {
    html += "<span class=\"c215x-hero-title\">Module " + next.n + ": " + c215Esc(next.title) + "</span>";
    html += "<span class=\"c215x-hero-sub\">" + next.lessons.length + " short lessons + a 10-question check</span></div>";
    html += "<button type=\"button\" class=\"c215x-btn-light\" onclick=\"c215CourseGo('module'," + next.n + ",0)\">Open module</button></div>";
  } else {
    html += "<span class=\"c215x-hero-title\">Final Practice Exam</span><span class=\"c215x-hero-sub\">All modules passed. Score 70% to get your certificate.</span></div>";
    html += "<button type=\"button\" class=\"c215x-btn-light\" onclick=\"c215CourseGo('final')\">Start exam</button></div>";
  }
  html += "<p class=\"c215c-tip\">Read the lessons, pass each 10-question check (80%), then pass the final (70%) to get your certificate.</p>";
  if (c215Course.certDate) { html += "<button type=\"button\" class=\"c215x-btn-soft\" onclick=\"c215CourseGo('cert')\">View my certificate</button>"; }
  html += "</div></div>";
  container.innerHTML = html;
}

function c215RunBreakdownHtml(r) {
  var html = "", i, e, missed = 0;
  for (i = 0; i < r.log.length; i++) { if (!r.log[i].ok) { missed++; } }
  html += "<div class=\"c215x-card c215c-review\"><div class=\"c215x-card-hd\"><h2>Question breakdown</h2><span>" + (r.log.length - missed) + " right -- " + missed + " to review</span></div>";
  if (!missed) { html += "<p class=\"c215c-facts\">Every answer was right. Nice work.</p>"; }
  for (i = 0; i < r.log.length; i++) {
    e = r.log[i];
    if (e.ok && r.kind === "final") { continue; }
    html += "<div class=\"c215c-rv" + (e.ok ? " is-ok" : " is-miss") + "\"><span class=\"c215c-rv-mark\">" + (e.ok ? "Right" : "Review") + "</span>";
    html += "<div class=\"c215c-rv-body\"><div class=\"c215c-rv-q\">" + e.q.q + "</div>";
    if (!e.ok) { html += "<div class=\"c215c-rv-a\">You picked: " + e.q.opts[e.picked] + "</div>"; }
    html += "<div class=\"c215c-rv-a\"><strong>Answer:</strong> " + e.q.opts[e.q.a] + "</div>";
    if (!e.ok) { html += "<div class=\"c215c-rv-e\">" + e.q.e + "</div>"; }
    html += "</div></div>";
  }
  html += "</div>";
  return html;
}

function c215RenderModule(container) {
  var mod = c215CourseFind(c215Course.mod), html = "", i, k, l, mins = 0, read = 0, terms = [], traps = [];
  if (!mod) { c215CourseGo("home"); return; }
  for (i = 0; i < mod.lessons.length; i++) {
    l = mod.lessons[i];
    mins += l.mins || 4;
    if (c215Course.read["m" + mod.n + "l" + i]) { read++; }
    for (k = 0; k < (l.terms || []).length; k++) { terms.push(l.terms[k]); }
    if (l.remember) { traps.push(l.remember); }
  }
  var qn = c215CourseQuestionsFor(mod.n).length;
  var best = c215Course.scores["m" + mod.n];
  var done = !!c215Course.done["m" + mod.n];
  html += "<div class=\"c215c-mod\">";
  html += "<div class=\"c215x-toolbar\"><button type=\"button\" class=\"c215x-btn-soft\" onclick=\"c215CourseGo('home')\">Back to course</button></div>";
  html += "<div class=\"c215x-hero c215c-mod-hero\"><div class=\"c215x-hero-txt\"><span class=\"c215x-eyebrow\">Module " + mod.n + " of " + c215CourseData().length + "</span>";
  html += "<span class=\"c215x-hero-title\">" + c215Esc(mod.title) + "</span><span class=\"c215x-hero-sub\">" + c215Esc(mod.sub) + "</span>";
  html += "<span class=\"c215c-chip\">" + mod.lessons.length + " lessons -- about " + mins + " min -- " + Math.min(10, qn) + "-question check</span></div>";
  html += "<div class=\"c215c-mod-cta\"><button type=\"button\" class=\"c215x-btn-light\" onclick=\"c215CourseGo('lesson'," + mod.n + ",0)\">" + (read ? "Keep reading" : "Start lesson 1") + "</button>";
  html += "<button type=\"button\" class=\"c215x-btn-glass\" onclick=\"c215CourseGo('check'," + mod.n + ",0)\">Take the check</button></div></div>";
  html += "<div class=\"c215c-mod-grid\">";
  html += "<div class=\"c215x-card\"><div class=\"c215x-card-hd\"><h2>What you will learn</h2><span>" + read + " of " + mod.lessons.length + " read</span></div><div class=\"c215c-mod-ls\">";
  for (i = 0; i < mod.lessons.length; i++) {
    l = mod.lessons[i];
    html += "<button type=\"button\" class=\"c215c-mod-l" + (c215Course.read["m" + mod.n + "l" + i] ? " is-read" : "") + "\" onclick=\"c215CourseGo('lesson'," + mod.n + "," + i + ")\">";
    html += "<span class=\"c215c-badge" + (c215Course.read["m" + mod.n + "l" + i] ? " is-done" : "") + "\">" + (i + 1) + "</span><span class=\"c215c-row-txt\"><span class=\"c215c-row-title\">" + c215Esc(l.title) + "</span>";
    html += "<span class=\"c215c-row-sub\">" + (l.mins || 4) + " min</span></span></button>";
  }
  html += "</div><div class=\"c215c-mod-status\">" + (done ? "Check passed -- best score " + best + "%" : (best ? "Best check score " + best + "%. 80% passes." : "Check not taken yet. 80% passes.")) + "</div></div>";
  html += "<div class=\"c215x-col\">";
  html += "<div class=\"c215x-card\"><h2>Test traps in this module</h2><ul class=\"c215c-traps\">";
  for (i = 0; i < traps.length; i++) { html += "<li>" + c215Esc(traps[i]) + "</li>"; }
  html += "</ul></div>";
  html += "</div></div></div>";
  container.innerHTML = html;
}

function c215RenderLesson(container) {
  var mod = c215CourseFind(c215Course.mod), html = "", i, l, k;
  if (!mod) { c215CourseGo("home"); return; }
  l = mod.lessons[c215Course.lesson];
  html += "<div class=\"c215c-lesson\">";
  html += "<div class=\"c215x-card c215c-side\"><button type=\"button\" class=\"c215x-btn-soft c215c-back\" onclick=\"c215CourseGo('home')\">Back to course</button>";
  html += "<span class=\"c215x-eyebrow-dark\">Module " + mod.n + " -- " + c215Esc(mod.title) + "</span>";
  html += "<button type=\"button\" class=\"c215c-lnk c215c-lnk-ov\" onclick=\"c215CourseGo('module'," + mod.n + ",0)\">Module breakdown</button>";
  for (i = 0; i < mod.lessons.length; i++) {
    html += "<button type=\"button\" class=\"c215c-lnk" + (i === c215Course.lesson ? " active" : "") + (c215Course.read["m" + mod.n + "l" + i] ? " is-read" : "") + "\" onclick=\"c215CourseGo('lesson'," + mod.n + "," + i + ")\">" + (i + 1) + ". " + c215Esc(mod.lessons[i].title) + "</button>";
  }
  html += "<button type=\"button\" class=\"c215c-lnk c215c-lnk-check\" onclick=\"c215CourseGo('check'," + mod.n + ",0)\">Module check (10 questions)</button></div>";
  html += "<article class=\"c215x-card c215c-read\">";
  html += "<span class=\"c215c-meta\">Lesson " + (c215Course.lesson + 1) + " of " + mod.lessons.length + " -- about " + (l.mins || 4) + " minutes</span>";
  html += "<h2 class=\"c215c-h\">" + c215Esc(l.title) + "</h2>";
  for (i = 0; i < l.body.length; i++) { html += "<p class=\"c215c-p\">" + c215Esc(l.body[i]) + "</p>"; }
  if (l.terms && l.terms.length) {
    html += "<h3 class=\"c215c-h3\">Key terms</h3><div class=\"c215c-terms\">";
    for (k = 0; k < l.terms.length; k++) {
      html += "<div class=\"c215c-term\"><div class=\"c215c-term-t\">" + c215Esc(l.terms[k].term) + "</div><div class=\"c215c-term-d\">" + c215Esc(l.terms[k].def) + "</div></div>";
    }
    html += "</div>";
  }
  if (l.remember) { html += "<div class=\"c215c-remember\"><strong>Remember for the test:</strong> " + c215Esc(l.remember) + "</div>"; }
  html += "<div class=\"c215c-nav\">";
  if (c215Course.lesson > 0) { html += "<button type=\"button\" class=\"c215x-btn-soft\" onclick=\"c215CourseGo('lesson'," + mod.n + "," + (c215Course.lesson - 1) + ")\">Previous</button>"; }
  else { html += "<span></span>"; }
  html += "<button type=\"button\" class=\"c215x-btn-dark\" onclick=\"c215CourseLessonNext()\">" + (c215Course.lesson < mod.lessons.length - 1 ? "Next lesson" : "Next: module check") + "</button>";
  html += "</div></article></div>";
  container.innerHTML = html;
}

function c215RenderRun(container) {
  var r = c215Course.run, html = "", q, i, cls, mod = c215CourseFind(c215Course.mod);
  var isFinal = r && r.kind === "final";
  var label = isFinal ? "Final practice exam" : "Module " + c215Course.mod + " check" + (mod ? " -- " + c215Esc(mod.title) : "");
  html += "<div class=\"c215x-focus\">";
  html += "<div class=\"c215x-toolbar\"><button type=\"button\" class=\"c215x-btn-soft\" onclick=\"c215CourseGo('home')\">Back to course</button>";
  if (!isFinal && mod) { html += "<button type=\"button\" class=\"c215x-btn-ghost\" onclick=\"c215CourseGo('lesson'," + mod.n + ",0)\">Review lessons</button>"; }
  html += "</div>";
  if (!r || !r.qs.length) {
    html += "<div class=\"c215x-card\">No questions yet for this module.</div></div>";
    container.innerHTML = html; return;
  }
  if (r.idx >= r.qs.length) {
    var need = isFinal ? C215_PASS_FINAL : C215_PASS_MODULE, passed = r.pct >= need;
    html += "<div class=\"c215x-qcard c215x-done\"><span class=\"c215x-eyebrow-dark\">" + label + "</span>";
    html += "<div class=\"c215-qz-pct\">" + r.pct + "%</div>";
    html += "<p class=\"c215x-done-sub\">" + r.correct + " of " + r.qs.length + " correct. " + (passed ? "You passed." : "You need " + need + "% to pass. Review the lessons and try again.") + "</p>";
    html += "<div class=\"c215x-actions\">";
    if (isFinal && passed) { html += "<button type=\"button\" class=\"c215x-btn-dark\" onclick=\"c215CourseGo('cert')\">Get my certificate</button>"; }
    else if (!isFinal && passed) {
      var nx = c215CourseNextModule();
      html += "<button type=\"button\" class=\"c215x-btn-dark\" onclick=\"c215CourseGo(" + (nx ? "'module'," + nx.n + ",0" : "'final'") + ")\">" + (nx ? "Start Module " + nx.n : "Start final exam") + "</button>";
    }
    html += "<button type=\"button\" class=\"c215x-btn-soft\" onclick=\"c215CourseGo('" + r.kind + "')\">Try again</button></div></div>";
    html += c215RunBreakdownHtml(r);
    html += "</div>";
    container.innerHTML = html; return;
  }
  q = r.qs[r.idx];
  html += "<div class=\"c215x-qmeta\"><span>" + label + "</span><span>Question " + (r.idx + 1) + " of " + r.qs.length + " -- " + r.correct + " correct</span></div>";
  html += "<div class=\"c215x-bar\"><div class=\"c215x-bar-fill c215x-bar-dark\" style=\"width:" + Math.round(r.idx / r.qs.length * 100) + "%\"></div></div>";
  html += "<div class=\"c215-qz-card c215x-qcard\"><div class=\"c215-qz-q\">" + q.q + "</div><div class=\"c215-qz-opts\">";
  for (i = 0; i < q.opts.length; i++) {
    cls = "c215-qz-opt";
    if (r.answered && i === q.a) { cls += " correct"; }
    else if (r.answered && i === r.picked) { cls += " wrong"; }
    html += "<button type=\"button\" class=\"" + cls + "\"" + (r.answered ? " disabled" : "") + " onclick=\"c215CourseAnswer(" + i + ")\"><span class=\"c215x-key\">" + String.fromCharCode(65 + i) + "</span><span class=\"c215x-opt-txt\">" + q.opts[i] + "</span></button>";
  }
  html += "</div>";
  if (r.answered) {
    var ok = r.picked === q.a;
    html += "<div class=\"c215-qz-explain show " + (ok ? "is-right" : "is-wrong") + "\">" + (ok ? "Correct. " : "Not quite. The answer is " + q.opts[q.a] + ". ") + q.e + "</div>";
  }
  html += "</div>";
  if (r.answered) { html += "<button type=\"button\" class=\"c215-qz-next show\" onclick=\"c215CourseNextQ()\">" + (r.idx < r.qs.length - 1 ? "Next question" : "See my score") + "</button>"; }
  html += "</div>";
  container.innerHTML = html;
}

function c215RenderCert(container) {
  var html = "";
  html += "<div class=\"c215x-focus\"><div class=\"c215x-toolbar\"><button type=\"button\" class=\"c215x-btn-soft\" onclick=\"c215CourseGo('home')\">Back to course</button></div>";
  if (!c215Course.certDate) {
    html += "<div class=\"c215x-card\"><h2>Your certificate</h2><p class=\"c215c-facts\">Your certificate is filled in with your final practice exam score once you score 70% or higher." + (c215Course.best ? " Best score so far: " + c215Course.best + "%." : "") + "</p>";
    html += "<button type=\"button\" class=\"c215x-btn-dark\" onclick=\"c215CourseGo('final')\">Start final exam</button></div></div>";
    container.innerHTML = html; return;
  }
  html += "<label class=\"c215c-name\">Your name for the certificate <input type=\"text\" maxlength=\"80\" value=\"" + c215Esc(c215Course.name) + "\" oninput=\"c215CourseSetName(this.value)\"></label>";
  html += "<div class=\"c215c-cert\" id=\"c215Cert\"><span class=\"c215c-cert-org\">Central Health Advisors</span>";
  html += "<span class=\"c215c-cert-title\">Certificate of Completion</span><span class=\"c215c-cert-sm\">This certifies that</span>";
  html += "<span class=\"c215c-cert-name\" id=\"c215CertName\">" + (c215Esc(c215Course.name) || "[Your name]") + "</span>";
  html += "<span class=\"c215c-cert-body\">completed the CHA 2-15 Course for New Agents and passed the final practice exam with a score of " + c215Course.best + "%.</span>";
  html += "<span class=\"c215c-cert-sm\">Completed " + c215Esc(c215Course.certDate) + "</span>";
  html += "<span class=\"c215c-cert-note\">CHA internal training record. This is not the Florida DFS-approved prelicensing certificate.</span></div>";
  html += "<div class=\"c215x-actions c215c-cert-actions\"><button type=\"button\" class=\"c215x-btn-dark\" onclick=\"c215CoursePrint()\">Print or save as PDF</button></div></div>";
  container.innerHTML = html;
}

function c215Init() {
  c215LoadStore();
  c215CourseLoad();
  var root = document.getElementById("cha-course215-root");
  if (root) { c215Render(); }
}

